<?php require 'config/database.php';session_start();$id=(int)($_GET['id']??0);$stmt=$conn->prepare("SELECT items.*,users.name AS owner_name FROM items JOIN users ON users.id=items.user_id WHERE items.id=?");$stmt->bind_param("i",$id);$stmt->execute();$item=$stmt->get_result()->fetch_assoc();if(!$item)die('Item not found');$msg='';if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_SESSION['user_id'])){if((int)$_SESSION['user_id']===(int)$item['user_id']){$msg='You cannot claim your own item.';}else{$message=trim($_POST['message']??'');if($message!==''){$user_id=$_SESSION['user_id'];$stmt=$conn->prepare("INSERT INTO claims(item_id,user_id,message,status) VALUES(?,?,?,'pending')");$stmt->bind_param("iis",$id,$user_id,$message);$msg=$stmt->execute()?'Claim request submitted.':'Could not submit claim.';}}}$pageTitle='Item Details';include 'header.php';?><h2><?=htmlspecialchars($item['title'])?></h2><div class="card"><?php if($item['image']):?><img class="item-img" src="uploads/<?=htmlspecialchars($item['image'])?>" alt="Item"><?php endif;?><p><strong>Type:</strong> <?=htmlspecialchars($item['item_type'])?></p><p><strong>Description:</strong> <?=nl2br(htmlspecialchars($item['description']))?></p><p><strong>Category:</strong> <?=htmlspecialchars($item['category'])?></p><p><strong>Location:</strong> <?=htmlspecialchars($item['location'])?></p><p><strong>Date:</strong> <?=htmlspecialchars($item['item_date'])?></p><p><strong>Status:</strong> <?=htmlspecialchars($item['status'])?></p><p><strong>Posted by:</strong> <?=htmlspecialchars($item['owner_name'])?></p></div><?php if($msg):?><div class="alert"><?=htmlspecialchars($msg)?></div><?php endif;?><?php if(isset($_SESSION['user_id'])&&(int)$_SESSION['user_id']!==(int)$item['user_id']):?><form method="post"><label>Claim Message</label><textarea name="message" required></textarea><button class="btn" type="submit">Send Claim Request</button></form><?php elseif(!isset($_SESSION['user_id'])):?><p><a class="btn" href="login.php">Login to Claim</a></p><?php endif;?><?php include 'footer.php'; ?>